export function homeHTML({link,toolCard,knownTool,favorites,recent,pathways,esc}){
 return `<section class="nav-home-hero"><span class="nav-card-kicker">SYMMETRY LAB · FROM UNDERSTANDING TO VERIFICATION</span><h1>Understand symmetry.<br>Put it to work in physics.</h1><p>Choose your starting point, then read, predict, calculate and explain along one learning path.</p></section>
 <section class="nav-path-section" aria-label="Three ways to begin"><div class="entry-levels">${[
 ['01',"Start with the basics","New to group theory","Explore symmetry operations, representations and characters, then move on to crystal symmetry.","Vectors and matrices",'classroom/foundations?lesson=group-basics',"Start the first lesson"],
 ['02',"Explore physical applications","Apply group theory to physics","Use phonons, selection rules and material responses to see how symmetry constrains observables.","Basic group theory and physics",'classroom/observables',"Choose a physics topic"],
 ['03',"Advanced tools and research","Have a calculation in mind?","Go directly to magnetic corepresentations, exact algebra, representation coupling and many-body models.","Representation theory and relevant physics",'compute',"Open the calculation center"]
 ].map(([n,title,who,goal,prior,route,action])=>`<article class="entry-level"><span class="entry-number">${n}</span><p class="entry-audience">${who}</p><h3>${title}</h3><p>${goal}</p><p class="entry-prior">Prerequisites: ${prior}</p>${link(route,action+' →','entry-action')}</article>`).join('')}</div></section>
 <section class="entry-flagship"><div><span class="nav-card-kicker">Foundations · Interactive Demos</span><h2>Understand Characters and Basis Functions, from Water Vibrations to Crystal-Field Levels.</h2><p>Explore D₃ triangle projections, SO(3) → O → D₄ splitting, IR and Raman polarizations, Jahn–Teller distortions, and macroscopic crystal symmetry.</p><p>${link('classroom/foundations?module=mini&experiment=polyhedra',"Explore Platonic Solids, Degenerate Bands, Permutations, and Spin →")}</p><p>${link('classroom/foundations?module=theorems&experiment=rearrangement',"Theorem Workshop: Rearrangement, Conjugacy, Normal Subgroups, Schur, and Orthogonality →")}</p></div>${link('classroom/foundations?module=demos&experiment=water',"Open the Foundational Demos →",'primary')}</section>
 <section class="entry-flagship"><div><span class="nav-card-kicker">FEATURED EXPERIMENT · ALLOW 25–35 MINUTES</span><h2>Why do Si, GaAs and BaTiO₃ have different second-harmonic responses?</h2><p>Predict the role of inversion, calculate the polarization response, then test your reasoning with a counterexample: an allowed response that vanishes.</p><p class="entry-flow">01 Predict → 02 Calculate → 03 Explain → 04 Test a counterexample</p></div>${link('classroom/observables?module=shg-story',"Start the SHG flagship experiment →",'primary')}</section>
 ${recent.length?`<section class="nav-tool-section"><h2>Continue learning and calculating</h2><div class="nav-recent">${recent.map(t=>link(t.route,esc(t.title))).join('')}</div></section>`:''}
 <section class="nav-tool-section"><h2>My favorite tools</h2>${favorites.length?`<div class="nav-card-grid">${favorites.map(r=>toolCard(knownTool(r),favorites)).join('')}</div>`:`<p class="nav-empty">Save your favorite tools for quick access next time.${link('compute',"Browse the calculation center →")}</p>`}</section>
 <details class="entry-directory"><summary>Explore all seven learning paths and every topic</summary><div class="nav-card-grid">${pathways.map(p=>link('classroom/'+p.id,`<h3>${p.title}</h3><p>${p.summary}</p>`,'nav-atlas-card')).join('')}</div><p>${link('atlas',"Browse groups and materials →")}　${link('atlas/projects',"Cross-module projects →")}　${link('docs/dictionary',"Formula and symbol dictionary →")}</p></details>`;
}
